import{_ as e,o as _,c as t,a3 as o}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/93-西武池袋线的学生不去池袋.md","filePath":"books/xialiu-shehui/93-西武池袋线的学生不去池袋.md","lastUpdated":1794732511000}'),p={name:"books/xialiu-shehui/93-西武池袋线的学生不去池袋.md"};function s(i,a,r,n,l,d){return _(),t("div",null,[...a[0]||(a[0]=[o('<h2 id="西武池袋线的学生不去池袋" tabindex="-1">西武池袋线的学生不去池袋 <a class="header-anchor" href="#西武池袋线的学生不去池袋" aria-label="Permalink to &quot;西武池袋线的学生不去池袋&quot;">​</a></h2><p>笔者在西武池袋线沿线练马区内的某所私立大学担任兼职讲师的时候，曾经询问过大约十个学生家住哪里，结果颇令人吃惊。记得大概有4个人与父母一起住在埼玉县内的池袋线沿线地区，其中有两个还是高中同学，其余的人多数住在茨城县和多摩新城，住所在东京都内的只有两个，分别住在江户川区和文京区，还有一个则住在神奈川县。</p><p>也就是说，即使上了大学，居住地也受到很大的限制。一流大学聚集着来自全国各地的学生，在这方面还具有多样性。然而如果是二流以下的大学，别说是特地从各地前来入学的学生少，就连越过各铁道沿线来入学的学生也很少。因而这些学校的学生，很多都住在同一个县内，或者是住在同一条铁道沿线。</p><p>笔者还记得，在港区和横滨市里的私立大学询问学生的住所时，他们多半说自己住在神奈川县。</p><p>虽说住在家里也没有什么不好，但是像大学这样的社会化的学习场所，本来不就需要具备多样性吗？既有来自东京山手圈内的富家子弟，也有从偏远地方来的贫寒学生，这样才能体现出大学作为社会缩影的意义。如今大学里已经没有贫寒的学生，只是聚集着住在同一铁道沿线新兴住宅区里的中流阶层的学生，大学生活再也不像以前那样充满刺激。</p><p>尤其令人惊讶的是，练马的大学生放学后很少有人会到池袋去，因为他们平时只是学校和家里两点一线，所以不会去池袋，更不用说去新宿这样的地方了。</p><p>笔者也是出生于地方小城的人，因而很能理解这种情况。其实在笔者的学生时代，期盼在东京大街上蹓跶的都是出生于地方小城的人，东京的大街在他们眼里全都视如珍宝，而且他们有一种对东京一无所知的劣等感，所以只想一古脑儿地逛遍东京的每个角落。但如果去问一下出生于东京的人，就会知道他们几乎不去自己家里沿线以外的地方，住在东横线一带的人不去池袋，也不常去吉祥寺，这是很平常的事情。因此，练马的大学生并没有什么异常之处，他们两点一线的生活也是很平常的。</p><p>不过，话说回来，笔者有时还是会对一直居住在父母家沿线并且满足于这种状态的现象感到相当疑惑。</p><p>为什么在20世纪60年代及70年代，年轻人的文化曾兴盛一时呢？其原因并不是年轻人自身充满了了不起的活力，而恰恰是因为当时东京等大都市聚集着众多来自全国各地的年轻人，不同的价值观在那里相互碰撞，进而形成充满活力的文化。</p>',9)])])}const u=e(p,[["render",s]]);export{h as __pageData,u as default};
